"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[940],{71940:function(e,t,a){a.d(t,{RX:function(){return r},XF:function(){return s},ck:function(){return n},jr:function(){return o}});let o={A:{title:"Foundations",subtitle:"stocks, flows & feedback — on the Simulate page"},B:{title:"Building models",subtitle:"the Build canvas & Godley tables"},C:{title:"Wiring",subtitle:"the dataflow canvas"},D:{title:"Agents & analysis",subtitle:"agent-based models and parameter sweeps"},E:{title:"The universal skeleton",subtitle:"the same dynamics in physics and economics"}},i=[{id:"compound-growth",track:"A",n:1,title:"Compound growth",scenario:"A savings account that grows on its own interest",estMinutes:5,concepts:["stock & flow","dx/dt = k\xb7x","growth vs decay","initial conditions"],surface:"simulate",modelId:"exponential",available:!0,steps:[{title:"Meet the stock",body:["Everything in the lab is built from {{stock|stocks}} — quantities that pile up over time — and the {{flow|flows}} that change them.","This first model is the simplest possible stock, `x`, growing at a rate proportional to its own size. That one rule is the whole model:"],formula:"dx/dt = k \xb7 x",highlight:"plot"},{title:"Run it",body:["The plot already shows the solution. With `k` positive, every moment adds a little more — and that little bit is bigger each time — so `x` curves upward. That's {{exponential-growth|exponential growth}}.","Think of a savings account: the more you have, the more interest you earn, so the more you have…"],highlight:"plot",apply:[{kind:"run"}]},{title:"Turn up the growth rate",body:["`k` is the growth rate — the knob that sets how fast `x` compounds. Let's push it up.","Watch the curve get dramatically steeper. Exponential growth is deceptively fast: small rate changes have huge long-run effects."],highlight:"param:k",apply:[{kind:"setParam",target:"k",value:.15}]},{title:"Make it shrink",body:["Now make `k` **negative**. A negative rate means `x` loses a fraction of itself each moment — **exponential decay**: radioactive decay, a leaking tank, a depreciating asset.","Same equation, opposite behaviour, just a sign change."],highlight:"param:k",apply:[{kind:"setParam",target:"k",value:-.08}]},{title:"The starting point",body:["`x0` is the **initial condition** — where the stock sits at t = 0. It scales the whole trajectory up or down but doesn't change its shape.","We've set `k` back to a gentle 0.05 and bumped the starting value. Every model you'll build has initial conditions like this."],highlight:"param:x0",apply:[{kind:"setParam",target:"k",value:.05},{kind:"setParam",target:"x0",value:5}]},{title:"What you learned",body:["You've met the core idea behind every model here: a **stock** plus a **rule for its rate of change**. Everything else — predators, wages, money, whole economies, populations of agents — is just more stocks and richer rules.","Next up: what happens when two stocks feed back on each other and start to oscillate."],apply:[{kind:"reset"}]}]},{id:"predator-prey",track:"A",n:2,title:"Predators & prey",scenario:"Boom-and-bust population cycles",estMinutes:7,concepts:["coupled stocks","feedback loops","oscillation","conserved quantity"],surface:"simulate",modelId:"lotka_volterra",available:!0,steps:[{title:"Two stocks, locked together",body:["Now we have **two** stocks — `prey` and `predator` — and each one's rate depends on the other. Prey breed on their own but get eaten; predators only grow by eating prey and starve without them.","That mutual dependence is a {{feedback-loop|feedback loop}}, and it's what makes the system come alive."],formula:"dprey/dt = α\xb7prey − β\xb7prey\xb7predator",highlight:"plot",apply:[{kind:"run"}]},{title:"The endless cycle",body:["Plenty of prey → predators boom → prey get eaten down → predators starve → prey recover → repeat.","Neither settles to a steady value; they chase each other round in a **cycle**, predators peaking just after the prey do."],highlight:"plot"},{title:"Predators die faster",body:["`gamma` is the predator death rate. Raise it and predators struggle — fewer of them means prey run higher before being checked.","Watch how one parameter reshapes both populations: in a coupled system nothing moves alone."],highlight:"param:gamma",apply:[{kind:"setParam",target:"gamma",value:2.2}]},{title:"A hungrier predator",body:["`beta` is how effectively predators catch prey. Turn it up and the predators crash the prey harder and faster — sharper, bigger swings.","Turn it too far and you flirt with a crash from which a population can't recover."],highlight:"param:beta",apply:[{kind:"setParam",target:"gamma",value:1.5},{kind:"setParam",target:"beta",value:.2}]},{title:"Where you start sets the orbit",body:["Change the starting number of prey. The cycle shifts to a different **orbit** — a bigger or smaller loop — but it still just goes round forever.","That's special: this idealized system has a {{conserved-quantity|conserved quantity}} (like energy) that pins each trajectory to a closed loop and never lets it spiral in or out."],highlight:"param:prey0",apply:[{kind:"setParam",target:"beta",value:.1},{kind:"setParam",target:"prey0",value:20}]},{title:"Why this matters",body:["Coupled stocks with feedback are the beating heart of *dynamics* — in ecology, epidemics, and, as we'll see next, **the economy itself**.","Goodwin's insight was that capitalism has exactly this predator–prey shape."],apply:[{kind:"reset"}]}]},{id:"goodwin-cycle",track:"A",n:3,title:"The Goodwin cycle",scenario:"Capitalism as a predator–prey system",estMinutes:10,concepts:["employment ↔ wage share","profit squeeze","closed orbits"],surface:"simulate",modelId:"goodwin",available:!0,steps:[{title:"Capitalism has a pulse",body:["In 1967 Richard Goodwin noticed the economy behaves like predator and prey. The two stocks here are the **employment rate** and the **wage share** of output.","Workers are the 'predators': when they're scarce (high employment) they bid up wages."],highlight:"plot",apply:[{kind:"run"}]},{title:"The profit squeeze",body:["Follow the loop: high employment → wages rise → the **wage share** climbs → profits get squeezed → firms invest less → growth slows → employment falls → wages ease → profits recover → firms invest → employment rises again.","It's the same closed cycle as predators and prey — just told in the language of macroeconomics."],highlight:"plot"},{title:"A more capital-hungry economy",body:["`nu` is the capital-to-output ratio — how much capital it takes to make a unit of output. It sets how fast profits turn into growth.","Nudge it and watch the cycle's period and centre shift."],highlight:"param:nu",apply:[{kind:"setParam",target:"nu",value:4}]},{title:"Read the two series together",body:["Both curves stay between 0 and 1 here — they're a share and a rate — and trace out closed loops: employment peaks, then the wage share peaks just after, exactly like prey then predator. (Start far from the centre and employment can overshoot 100% — a known quirk of the bare Goodwin model that later refinements fix.)","This is the archetype behind Steve Keen's models; the monetary machinery we build next bolts onto this skeleton."],highlight:"param:nu",apply:[{kind:"setParam",target:"nu",value:3}]},{title:"Peek at the equations",body:["Open the **Equations** tab to see exactly what the engine is integrating — the wage-share and employment ODEs plus the auxiliary profit share.","Every model in the lab exposes its compiled equations like this; nothing is hidden."],highlight:"tab:equations",apply:[{kind:"showTab",target:"equations"}]},{title:"From cycles to money",body:["You've now seen the economy modelled as {{endogenous|endogenous}} cycles — booms and busts as an *internal* feature, not an outside shock.","Next track: build models yourself, starting with growth that hits a ceiling, then the double-entry accounting that lets money itself be modelled."],apply:[{kind:"showTab",target:"plot"},{kind:"reset"}]}]},{id:"build-from-scratch",track:"B",n:4,title:"Build a model from scratch",scenario:"Limits to growth (logistic) & an epidemic (SIR)",estMinutes:12,concepts:["the Build canvas","reading a model graph","clone & edit","save"],surface:"build",modelId:"logistic",available:!0,steps:[{title:"This is the Build canvas",body:["We've loaded the **logistic** model — growth that runs into a ceiling. The canvas shows a model as a graph: blue **parameters** feed the equations, green **stocks** accumulate, purple **auxiliaries** are computed shorthands.","The arrows are dependencies the app read straight out of the equations."],highlight:"build:canvas"},{title:"Read the rule",body:["Logistic growth is `dx/dt = r\xb7x\xb7(1 − x/K)`. When `x` is small it grows like our very first model; as `x` nears the {{carrying-capacity|carrying capacity}} `K`, the `(1 − x/K)` term chokes it off — producing an S-curve instead of a runaway.","Click the `x` node to inspect its equation, or any parameter to see its value."],highlight:"build:canvas"},{title:"Built-ins are read-only",body:["You can't edit a built-in model directly — that keeps the originals pristine. Instead you **clone** it to get your own editable copy.","Click **Clone to edit** (highlighted). Now the palette in the inspector lets you add parameters, stocks and auxiliaries, and rename or retune anything."],highlight:"build:clone"},{title:"Make it yours",body:["Try it: select the `r` node and change its value, or add a new auxiliary. The graph and the compiled equations update live.","This is exactly how you'd assemble the **SIR epidemic** model from nothing — three stocks (S, I, R) and two flows (infection, recovery). It already ships as a built-in, so clone `sir` from the sidebar afterwards to see it wired up."],highlight:"build:canvas"},{title:"Save & run it",body:["When you're happy, **Save** stores your model, and it appears under *Saved models* everywhere in the app.","Then use **Open in Simulate →** to jump to the sliders-and-plots view and explore what you built."],highlight:"build:save"},{title:"You can build anything",body:["Parameters, stocks, auxiliaries and equations are all you need to express an enormous range of dynamics.","Next: the one ingredient that makes *monetary* models special — double-entry Godley tables."]}]},{id:"godley-intro",track:"B",n:5,title:"A balance sheet in motion",scenario:"Money is created by lending",estMinutes:12,concepts:["double-entry","stock-flow consistency","money creation"],surface:"simulate",modelId:"monetary",available:!0,steps:[{title:"Money is somebody's IOU",body:["This is a minimal economy with a single **bank**. Its stocks are balance-sheet entries: loans (the bank's asset) and everyone's deposits (the bank's liabilities).","The trick that makes it *monetary* is {{double-entry|double-entry accounting}} — every flow is recorded twice, so the books always balance."],highlight:"plot",apply:[{kind:"run"}]},{title:"See the Godley table",body:["Open the **Godley table** tab. Columns are accounts (assets `+`, liabilities/equity `−`); rows are flows. Read a row across and it tells you where money moves.","The golden rule: **every row sums to zero** under those signs. Nothing appears from nowhere."],highlight:"tab:godley",apply:[{kind:"showTab",target:"godley"}]},{title:"Lending creates money",body:["Look at the `lend` row: it adds to `Loans` (an asset) *and* to `FirmDep` (a deposit) at the same time. The bank didn't move existing money — it {{money-creation|created new money}} by making a loan.","That's not a metaphor; it's how bank money actually works, and the accounting proves it stays consistent."],highlight:"tab:godley"},{title:"Turn on net lending",body:["By default lending equals repayment, so the same money just circulates. Now push `lend_rate` above `repay_rate` and go back to the plot.","The money supply and debt both grow — visible money creation."],highlight:"param:lend_rate",apply:[{kind:"showTab",target:"plot"},{kind:"setParam",target:"lend_rate",value:.2}]},{title:"The invariant never breaks",body:["Plot the `net_worth_check` series (toggle it on): it stays pinned at ~0 no matter what you do. That's assets = liabilities + equity holding at every instant — the model is {{stock-flow-consistency|stock-flow consistent}} by construction.","This is what Godley tables buy you: you literally cannot write down an inconsistent monetary model."],highlight:"plot"},{title:"Why Keen cares",body:["Mainstream models often leave banks and money out entirely. Godley tables put them at the centre and keep the accounting honest — the foundation of Keen's critique.","Next: extend this economy with a **government** that spends and taxes."],apply:[{kind:"reset"}]}]},{id:"extend-monetary",track:"B",n:6,title:"Extend a monetary model",scenario:"Add a government sector: spending & taxes",estMinutes:15,concepts:["growing a Godley table","keeping rows balanced","deficits create money"],surface:"build",modelId:"monetary_gov",available:!0,steps:[{title:"The economy grows a government",body:["We've loaded **monetary_gov** — the same bank circuit, now with a government sector holding a `GovDep` account. The canvas shows the extra stock and flows.","This is how you extend an SFC model: add accounts and flows, keeping every row balanced."],highlight:"build:canvas"},{title:"Open the Godley table",body:["Click the **Godley** tab in the inspector (clone first if prompted). You'll see three new flows: `spending`, `tax_firm` and `tax_worker`.","Each still sums to zero. `spending` credits firms' deposits and debits the government (`GovDep −1`); taxes do the reverse."],highlight:"build:godley"},{title:"Deficits are money creation",body:["When the government spends more than it taxes, `GovDep` goes **negative** — that's the government 'deficit' — and the private sector's deposits rise by exactly the same amount.","In this accounting, a government deficit literally *adds* net money to the private economy. Surpluses drain it."],highlight:"build:godley"},{title:"Try changing a flow",body:["After cloning, edit the `spending` expression or a tax coefficient in the Godley editor. The balance indicator (`Σ`) turns red the instant a row stops summing to zero — the app won't let you cheat the accounting.","Fix it back to green and you've got a valid model again."],highlight:"build:godley"},{title:"Save & explore",body:["Save your version, then **Open in Simulate →** and toggle on `private_money` and `GovDep`. Crank `gov_spend` up and watch private money grow while the government's balance sinks.","You've just reproduced the sectoral-balances logic behind a core MMT claim — straight from balanced accounting. (This toy runs the government's account through the bank; the real plumbing goes via the central bank and treasury, but the accounting logic is the same.)"],highlight:"build:save"},{title:"You can model any sector",body:["Households, firms, banks, government, the rest of the world — each is just another column, each transaction just another balanced row.","Next track: instead of typing equations, you'll *wire* models together on a canvas."]}]},{id:"monetary-nation",track:"B",n:7,title:"Anatomy of a monetary nation",scenario:"How the pieces of a real economy connect",estMinutes:20,concepts:["sectors & balance sheets","the bond market","sectoral balances","government ≠ household"],surface:"simulate",modelId:"sfc_nation",available:!0,steps:[{title:"A whole economy on one balance sheet",body:["We've loaded **Anatomy of a monetary nation** — households, firms, banks and a consolidated government (Treasury + central bank), all on a single {{stock-flow-consistency|stock-flow consistent}} balance sheet. This is the plumbing behind arguments about deficits, debt and money.","Every arrow is a {{double-entry|double-entry}} transaction: money only ever *moves* between accounts, so the books always balance. Hit run and watch the economy settle into a steady state — then we'll take it apart piece by piece.","Read the companion article first if you like: [Anatomy of a monetary nation](/wiki?a=monetary-nation)."],highlight:"plot",apply:[{kind:"run"}]},{title:"Who holds what",body:["Open the **Godley table** tab. Each column is an account; each row is a flow. The stocks are the sectors' balance sheets:","**Households** hold `HHDep` (money) and `HHBonds` (government bonds). **Firms** hold `FirmDep` and owe `Loans` — that's {{private-debt|private debt}}. **Banks** hold the loans and owe the deposits. **The state** owes `GovDep` (its account — negative means it has spent money into existence) and `GovBonds` (the {{public-debt|public debt}}).","Read any row across: it always nets to zero under the signs (assets `+`, liabilities `−`). Nothing appears from nowhere."],highlight:"tab:godley",apply:[{kind:"showTab",target:"godley"}]},{title:"The private circuit",body:["Back to the plot. Toggle on `HHDep` and `FirmDep`. Firms pay **wages** (money flows firms → households) and households **consume** (money flows back households → firms). That loop is the private economy turning over.","Notice the money doesn't leak away — it just circulates. To grow the total, something has to *create* new money. There are two ways, and you're about to see both."],highlight:"tab:plot",apply:[{kind:"showTab",target:"plot"}]},{title:"Banks create money by lending",body:["The first money-maker is private banks. A bank loan creates a deposit *at the same instant* — new money that didn't exist before. That's {{money-creation|money creation}}, and it's {{endogenous|endogenous}}: it comes from inside the private economy.","Push `lend_rate` above `repay_rate` (we'll set it to 0.14) and toggle on `Loans` and `private_money`. Both climb — visible money creation, and a growing stack of private debt.","Keep the gap modest: sustained net lending compounds, and a big gap runs debt to the moon — which is exactly Keen's point about how private-debt booms end. See [Keen on endogenous money](/wiki?a=keen-endogenous-money)."],formula:"a loan creates a deposit:  Loans +1,  FirmDep +1",highlight:"param:lend_rate",apply:[{kind:"setParam",target:"lend_rate",value:.14},{kind:"run"}]},{title:"The government spends money into existence",body:["The second money-maker is the state. A {{currency-issuer|currency issuer}} doesn't need to collect money before it spends — it spends by *crediting* a household's deposit, and `GovDep` goes **negative**. That negative balance is {{base-money|base money}}: the money the state has injected and not yet taxed back.","We've reset the model and turned `gov_spend` up to 40. Toggle on `base_money` and `hh_wealth` and watch both rise. The government isn't running out of anything — it's issuing its own IOU."],highlight:"param:gov_spend",apply:[{kind:"reset"},{kind:"setParam",target:"gov_spend",value:40},{kind:"run"}]},{title:"Taxes destroy money",body:["If spending creates money, taxes do the opposite: they *delete* it from the private sector. Raise `tax_rate` and watch `private_money` and `hh_wealth` fall.","So the government's job isn't to 'collect money so it can spend' — it spends first and taxes after. Taxes drain money (to control inflation and make room), they don't fund the spending that already happened."],highlight:"param:tax_rate",apply:[{kind:"setParam",target:"tax_rate",value:.28},{kind:"run"}]},{title:"The deficit is the private surplus",body:["Here's the punchline of the whole model. Reset, then toggle on **just** `private_nfw` and `gov_nw`. They are perfect mirror images: the government's net worth going down *is* the private sector's net financial wealth going up, dollar for dollar.","This is the {{sectoral-balances|sectoral balances}} identity — an accounting fact, not an opinion. A government deficit doesn't 'crowd out' private saving; it *is* private saving. See [deficits & surpluses](/wiki?a=godley-sectoral-balances)."],formula:"private_nfw + gov_nw = 0   (always, to the penny)",highlight:"plot",apply:[{kind:"reset"},{kind:"run"}]},{title:"Enter the bond market",body:["So far the state's IOU has just been base money. The {{bond-market|bond market}} lets savers swap that money for interest-bearing government bonds. It's a {{portfolio-choice|portfolio choice}}: `bond_pref` is the share of wealth households want to hold as bonds instead of money.","Turn `bond_pref` up and toggle on `public_debt` and `base_money`. Savings shift out of money and into bonds — the 'national debt' rising is simply the public choosing to hold more of its wealth as bonds. At the moment of purchase it's a pure swap: your deposit becomes a bond, your wealth unchanged.","This is the piece most people get backwards — [how the bond market actually works](/wiki?a=bond-market)."],formula:"buy a bond:  HHDep −1,  HHBonds +1   (a swap, not a payment)",highlight:"param:bond_pref",apply:[{kind:"setParam",target:"bond_pref",value:.6},{kind:"run"}]},{title:"Public debt service is private income",body:["What do bonds *add*, if buying one is just a swap? Interest. And since the government pays that interest, **the cost of the public debt is, dollar for dollar, income to the private sector**.","Turn `r_bond` (the policy interest rate) up and watch `hh_wealth` and `private_nfw` grow faster — the interest on the debt is flowing straight into household pockets. 'Debt service' and 'private income' are two names for the same arrows."],highlight:"param:r_bond",apply:[{kind:"setParam",target:"r_bond",value:.08},{kind:"run"}]},{title:"Quantitative easing, demystified",body:["The central bank can run the swap in reverse. **QE** is the state buying its own bonds back with newly created money — turning `GovBonds` back into `base_money`. Turn `qe` up and watch `public_debt` fall.","If the government can conjure money to buy back its own debt whenever it likes, that debt was never the hard constraint people imagine. The real limits are inflation and real resources — not solvency."],highlight:"param:qe",apply:[{kind:"reset"},{kind:"setParam",target:"qe",value:.5},{kind:"run"}]},{title:"The government is not a household",body:["Put it together. A household must get money before it spends and can go broke. The state issues the money, spends it into existence, taxes some back, and lets the public park the rest in bonds it can always buy back. Same accounting throughout — `net_worth_check` never budged from zero — but a completely different set of constraints.","That's the case at the heart of this whole project: [the government is not a household](/wiki?a=government-not-household). You didn't have to take anyone's word for it — you ran the plumbing yourself."],apply:[{kind:"reset"}]}]},{id:"wire-first-model",track:"C",n:8,title:"Wire your first model",scenario:"From k\xb7x to logistic, by wiring operators",estMinutes:12,concepts:["dataflow paradigm","wires → equations","feedback via integrals"],surface:"wire",available:!0,steps:[{title:"Models as circuits",body:["This is the **Wire** canvas. Instead of typing equations, you drop nodes and connect them; the app **compiles the wiring into equations** and runs it. The Wire canvas is inspired by Steve Keen's open-source Minsky software; Encode Reality Lab is an independent implementation, not affiliated with that project.","The example loaded — **Savings account** — is `dx/dt = k\xb7x`: a parameter `k`, an integral (stock) `x`, and a `\xd7` operator, wired in a loop. On the left is a whole gallery of worked examples, each with a step-by-step walkthrough on the right."],highlight:"wire:canvas"},{title:"Read the wiring",body:["Follow the arrows: `k` and `x` both feed the `\xd7` node, and its output feeds back into `x`'s rate of change. The stock's output looping back is what makes it *feedback* — and it's legal precisely because an integral breaks the algebraic loop.","Look at the **Compiled equations** panel on the left: the graph became `d x/dt = k*x`."],highlight:"wire:run",apply:[]},{title:"The palette",body:["Up top is the node palette: **sources** (parameters, constants, variables, stocks, time), **operators** (`+ − \xd7 \xf7 ^` and functions like `exp`, `√`), and the Godley **widget**.","Drag from a node's output handle to another's input handle to wire them. One wire per input."],highlight:"wire:palette"},{title:"Build toward logistic",body:["Logistic growth is `r\xb7x\xb7(1 − x/K)`. You'd add a parameter `K`, a `\xf7` to form `x/K`, a `−` against a constant `1`, and a `\xd7` chain — then wire the result into the stock's rate.","Take a minute to add a couple of nodes and wire them; **Compile & run** shows the equation and the plot instantly. (The **Limits to growth** example in the gallery is exactly this, finished — load it to check your wiring.)"],highlight:"wire:palette"},{title:"Compile & run",body:["Hit **Compile & run** any time. If a wire is missing or an operator input is dangling, you get a clear error; otherwise you get equations and a live plot below the canvas.","When it looks right, **Save model** keeps it alongside everything else."],highlight:"wire:run",apply:[{kind:"run"}]},{title:"Same engine, different door",body:["Wiring and typing produce the *same* kind of model — both compile down to the ODE system the engine integrates. Use whichever fits how you think.","Next: put a Godley table right onto the canvas and wire behaviour into it."]}]},{id:"wire-monetary",track:"C",n:9,title:"Wire a monetary circuit",scenario:"A Godley widget with a behavioural flow",estMinutes:15,concepts:["Godley on the canvas","account outputs & flow inputs"],surface:"wire",available:!0,steps:[{title:"Load the wired bank",body:["In the gallery, click the **Bank that lends** example (highlighted). This puts a **Godley table as a node** on the canvas — the accounting and the wiring, together. That pairing is the idea behind Steve Keen's open-source Minsky software, which inspired this canvas; Encode Reality Lab is an independent implementation, not affiliated with that project.","This is the signature wire-plus-Godley workflow."],highlight:"wire:godley-example"},{title:"Accounts are outputs, flows are inputs",body:["On the Godley node, each **account column** exposes an output port on top (green) — you can wire an account's live balance into a computation. Each **flow row** exposes an input port on the left — you can wire a computed value *into* the flow.","So a flow's behaviour can depend on the state of the economy."],highlight:"wire:canvas"},{title:"Behaviour, wired",body:["In this example the `lend` flow is fed by `lend_rate \xd7 Loans`: the `Loans` account output goes into a `\xd7` node with the `lend_rate` parameter, and the result wires back into the `lend` flow input.","Read the **Compiled equations**: `lend = Loans*lend_rate`, and both `Loans` and `Deposit` grow — money creation, assembled by wiring."],highlight:"wire:run",apply:[{kind:"run"}]},{title:"Extend it",body:["Try wiring a different behaviour — for instance make lending respond to the interest rate, or add a repayment flow proportional to `Loans`.","Add nodes from the palette, wire them into a flow input, and **Compile & run**. The Godley editor (click the node) lets you add accounts and flows too."],highlight:"wire:palette"},{title:"Balance is enforced",body:["Because it's a Godley table, every flow row must still net to zero. The node's editor shows the balance per row; the compiler refuses inconsistent tables.","You get behavioural freedom *and* airtight accounting at once."],highlight:"wire:canvas"},{title:"The full stock-flow workflow",body:["Accounts as outputs, flows as inputs, behaviour wired in, accounting guaranteed — that's what makes this style so powerful for monetary economics.","Final track: agent-based models and sweeping the parameter space."]}]},{id:"abm-vs-ode",track:"D",n:10,title:"When averages lie",scenario:"ODE vs agent-based predator–prey",estMinutes:10,concepts:["what an ABM is","stochasticity","extinction","seeds"],surface:"simulate",modelId:"predator_prey_abm",available:!0,steps:[{title:"Same story, different engine",body:["Remember the smooth predator–prey cycles? This is the **agent-based** version. Instead of an equation for the average, it simulates *individual* prey and predators, each with its own energy, hunting and dying one by one.","The aggregate counts are **measured**, not assumed."],highlight:"plot",apply:[{kind:"run"}]},{title:"Notice the jaggedness",body:["The cycles are there, but they're **noisy** — ragged, irregular, alive. That randomness is real: it comes from discrete individuals and chance encounters, not from an idealized average.","No smooth ODE can produce this texture."],highlight:"plot"},{title:"Change the seed, change history",body:["An ABM is **stochastic**. The `seed` fixes the random draws so runs are reproducible — but change it and you get a *different history* from the same rules.","Try a new seed: the broad rhythm survives, the details don't. Real systems are like this."],highlight:"param:seed",apply:[{kind:"setParam",target:"seed",value:123}]},{title:"Push it toward collapse",body:["We've switched off the model's safety nets — the **prey refuge** and **predator immigration** — and cranked up hunting. In the tidy ODE, predators and prey cycle forever. Here the squeeze drives a population to **extinction** — and once it hits zero, it's gone for good.","Averages can't go extinct; individuals can. Change the seed and it still collapses — just at a different moment."],highlight:"param:hunt_rate",apply:[{kind:"setParam",target:"prey_refuge",value:0},{kind:"setParam",target:"predator_immigration",value:0},{kind:"setParam",target:"hunt_rate",value:.9}]},{title:"Why this matters for economics",body:["ODEs assume a smooth, representative average exists. But heterogeneity, discreteness and chance can produce outcomes — extinctions, crashes, tipping points — that the average completely misses.","That's the whole case for ABMs: sometimes the average lies."],apply:[{kind:"setParam",target:"hunt_rate",value:.5},{kind:"reset"}]},{title:"Onward to systemic risk",body:["Next we take this idea to finance: a network of firms where individual failures can cascade into a system-wide collapse."]}]},{id:"credit-cascade",track:"D",n:11,title:"Systemic risk & tipping points",scenario:"Bankruptcy cascades on a network",estMinutes:12,concepts:["heterogeneous agents","contagion","emergent collapse"],surface:"simulate",modelId:"credit_cascade",available:!0,steps:[{title:"An economy of firms",body:["Here are hundreds of individual **firms**, each with an equity buffer, wired into a random network of who-owes-whom. Each step every firm takes a random profit/loss shock.","When a firm's equity hits zero it **defaults** — and its creditors take a loss."],highlight:"plot",apply:[{kind:"run"}]},{title:"Contagion",body:["A default isn't the end of the story: the loss it imposes can push a creditor under too, which hits *their* creditors — a **cascade** that resolves within a single step.","Watch `solvent_firms` and the `defaults_step` spikes: failures cluster, they don't arrive evenly."],highlight:"plot"},{title:"Calm by default",body:["With mild shocks the system is stable — a healthy economy where defaults are rare and isolated. Nothing dramatic.","Now let's stress it."],highlight:"param:shock_vol"},{title:"The tipping point",body:["Turn up `shock_vol` (shock volatility). Below a threshold, damage stays contained. Past it, the system **tips** — a single bad draw triggers a chain reaction that wipes out most firms at once.","That nonlinear cliff is {{emergence|emergent}}: no single firm decides it; it comes from the network."],highlight:"param:shock_vol",apply:[{kind:"setParam",target:"shock_vol",value:4.5}]},{title:"More links, more fragility",body:["Counter-intuitively, denser connections (`exposure`, `avg_degree`) can make things *worse* — they spread losses faster. Robustness and fragility are properties of the **whole network**, not the parts.","This is exactly the systemic-risk story behind 2008."],highlight:"param:exposure",apply:[{kind:"setParam",target:"exposure",value:8}]},{title:"From one run to the whole map",body:["One run is one history. To find *where* the tipping point actually is, you need to sweep the parameters and map the regimes — which is exactly what Atlas is for.","Reset, and let's go map it."],apply:[{kind:"setParam",target:"shock_vol",value:1},{kind:"setParam",target:"exposure",value:3},{kind:"reset"}]}]},{id:"sweeps-atlas",track:"D",n:12,title:"Mapping the regime",scenario:"Parameter sweeps with Atlas",estMinutes:12,concepts:["sensitivity analysis","2-D sweeps","regime boundaries"],surface:"atlas",modelId:"goodwin",available:!0,steps:[{title:"Beyond a single run",body:["One simulation answers 'what happens *here*?'. **Atlas** answers 'what happens *everywhere*?' by running a model across a whole grid of parameter values and summarising each run into one number.","We've loaded the Goodwin cycle to sweep."],highlight:"atlas:model"},{title:"Pick two dimensions",body:["Choose a **rows** parameter and a **columns** parameter, each with a from/to range and a number of steps. Atlas runs every combination — a 2-D map of the parameter space.","For Goodwin, try sweeping `alpha` against `beta` (productivity vs population growth)."],highlight:"atlas:model"},{title:"Choose what to measure",body:["For each run, reduce a time series to a single value: its `last` value, `mean`, `min`, `max`, or `amplitude`. Amplitude of the wage share tells you *how violent* the cycle is at each point.","Then hit **Run sweep**."],highlight:"atlas:run"},{title:"Read the heat-map",body:["The pivot shades each cell by value — bright = high. Now you can *see* the structure: where cycles are gentle, where they blow up, where a regime boundary runs.","This is **sensitivity analysis**: which knobs matter, and where behaviour changes qualitatively."],highlight:"atlas:pivot"},{title:"Rotate & reorient",body:["Hit **⟲ rotate** to swap the row and column dimensions — the same data, seen from another angle. That reorientation is the essence of Atlas: slice multidimensional results however you need.","The CSV-pivot tab does the same for any dataset you upload."],highlight:"atlas:pivot"},{title:"You've closed the loop",body:["Simulate → build/wire → analyse. Sweeping turns a model from an anecdote into a map, and maps are where you find tipping points and design levers.","One tutorial left: put it all together."]}]},{id:"capstone",track:"D",n:13,title:"Capstone",scenario:"Model a scenario end-to-end",estMinutes:30,concepts:["synthesis","build → simulate → sweep → interpret"],surface:"simulate",available:!0,steps:[{title:"Now it's your turn",body:["You've met every tool: stocks & flows, Godley accounting, ODE and agent-based engines, wiring, and parameter sweeps. This capstone is a loose project to tie them together.","Pick a question you actually care about."]},{title:"1 — Pose a question",body:["Something you can express as stocks and flows. For example: *Does a government job-guarantee stabilise employment?* *How does household debt drive a boom-bust?* *When does a supply shock tip an industry into collapse?*","A good question names the stocks you care about and the lever you want to test."]},{title:"2 — Build or wire it",body:["In **Build**, clone the closest model (`monetary_gov`, `goodwin`, `logistic`) and modify it — add a sector, a feedback, a policy rule. Or start from scratch in **Wire**.","Keep every Godley row balanced; let the validator be your safety net."]},{title:"3 — Simulate & interpret",body:["Open it in **Simulate**, move the sliders, and build intuition for the behaviour. Which parameters flip it between regimes? What surprises you?","Toggle series on and off; read the compiled equations to check it's doing what you think."]},{title:"4 — Map it with Atlas",body:["Sweep your key parameters and find the boundaries — the deficit level that stabilises, the debt ratio that tips, the shock size that cascades.","That map is your answer, and it's far more convincing than a single run."]},{title:"You're a modeller now",body:["Everything here — the whole lab — exists so you can turn an economic question into a runnable, inspectable, honest model.","Go build something. And if you get stuck, every earlier tutorial is one click away."]}]},{id:"same-oscillator",track:"E",n:14,title:"The same oscillator",scenario:"A spring, a circuit and a business cycle are one equation",estMinutes:10,concepts:["structural isomorphism","conserved energy ↔ invariant","damping ↔ friction ↔ resistance"],surface:"simulate",modelId:"harmonic_oscillator",available:!0,steps:[{title:"A mass on a spring",body:["This is pure physics: a {{harmonic-oscillator|mass bouncing on a spring}}. Two stocks — **position** `x` and **velocity** `v` — feed each other, and the system swings.","`dx/dt = v`; the velocity changes with the spring's pull and any friction. Watch it oscillate."],formula:"dv/dt = −(k/m)\xb7x − (c/m)\xb7v",highlight:"plot",apply:[{kind:"run"}]},{title:"Take the friction away",body:["Set the damping `c` to 0. Now nothing drains the motion — it rings **forever**, because the {{conserved-quantity|energy is conserved}}. Toggle the `energy` series on: it's a flat line.","That conserved energy is the *exact* counterpart of the conserved quantity that kept the predator–prey and Goodwin orbits closed loops."],highlight:"param:c",apply:[{kind:"setParam",target:"c",value:0}]},{title:"Add damping back",body:["Now turn `c` up. Friction bleeds energy away each swing and the mass spirals to rest — a {{damping|damped}} oscillation.","A real spring, a plucked string, a shock absorber: all this same picture."],highlight:"param:c",apply:[{kind:"setParam",target:"c",value:.5}]},{title:"You've seen this before",body:["Here's the twist. We'll switch to the **Goodwin cycle** — an *economic* model of employment and the wage share.","It's the **same oscillator**. Employment plays the role of position, the wage share of velocity; they trade back and forth exactly as `x` and `v` do. The economy is running the physics of a spring."],highlight:"plot",apply:[{kind:"selectModel",target:"goodwin"}]},{title:"…and in a circuit",body:["One more: an **RLC electrical circuit**. Charge and current obey *identical* equations to the mass–spring — swap position↔charge, velocity↔current, spring↔1/capacitance, mass↔inductance, friction↔resistance.","Physicist, engineer, economist: three people studying one object with different words."],highlight:"plot",apply:[{kind:"selectModel",target:"rlc_circuit"}]},{title:"One skeleton",body:["Stocks, flows, feedback, a conserved quantity, damping — the {{structural-isomorphism|structure}} is what matters, not the stuff. That's the throughline of the whole lab.","Read **The same equations everywhere** in the Wiki, then meet the cycles that *sustain themselves*."],apply:[{kind:"selectModel",target:"harmonic_oscillator"}]}]},{id:"self-sustaining-cycles",track:"E",n:15,title:"Cycles that sustain themselves",scenario:"Limit cycles, business cycles, and the edge of chaos",estMinutes:10,concepts:["limit cycle ↔ endogenous cycle","deterministic chaos","the limits of forecasting"],surface:"simulate",modelId:"van_der_pol",available:!0,steps:[{title:"A cycle that won't die",body:["The mass–spring needed a push and eventually stopped. The **Van der Pol oscillator** is different: its damping is {{nonlinear-damping|nonlinear}} — it pumps energy in when the swing is small and out when it's large.","The result is a {{limit-cycle|limit cycle}}: it settles into a steady, self-sustaining oscillation on its own."],highlight:"plot",apply:[{kind:"run"}]},{title:"It finds the same loop from anywhere",body:["Start it from a very different place. It spirals right back onto the *same* cycle. The oscillation isn't imposed from outside — the system **organises it from within**.","That's the key property, and it's what a spring can't do."],highlight:"param:x0",apply:[{kind:"setParam",target:"x0",value:3}]},{title:"This is the business cycle",body:["Now the economic twin — the **Goodwin cycle** again, but read it with new eyes. Booms and busts here aren't caused by outside shocks; the {{feedback-loop|feedback}} between wages, profit and investment **generates** them.","That's exactly [Minsky and Keen's](/wiki?a=hyman-minsky) claim: capitalist economies are limit-cycle machines. They don't need to be hit to swing — they pump their own oscillation, like Van der Pol's circuit."],highlight:"plot",apply:[{kind:"selectModel",target:"goodwin"}]},{title:"When it tips into chaos",body:["Add a third stock and the right feedback and you get the **Lorenz system**, which shows {{chaos|deterministic chaos}} — it never repeats and can't be predicted far ahead. A one-in-a-thousand change to the start explodes into a totally different history.","It's the physicist's hard-won humility about the weather — and a warning to anyone who claims to forecast a complex economy years out from its equations."],highlight:"plot",apply:[{kind:"selectModel",target:"lorenz"}]},{title:"The whole map",body:["Growth, relaxation, saturation, oscillation, self-sustaining cycles, chaos, emergence — a handful of skeletons, each wearing a physical *and* an economic costume.","You now have the whole vocabulary. The Wiki's **universal skeleton** section ties it together."],apply:[{kind:"selectModel",target:"van_der_pol"}]}]}];function n(e){return i.find(t=>t.id===e)}function s(e){return i.filter(t=>t.track===e).sort((e,t)=>e.n-t.n)}function r(e){let t=e.modelId?"?model=".concat(e.modelId,"&tutorial=").concat(e.id):"?tutorial=".concat(e.id),a="simulate"===e.surface?"/":"/".concat(e.surface);return"".concat(a).concat(t)}}}]);